import sys
from pathlib import Path

sys.path.insert(0, '/testbed/src')
from cfnlint.template import Template
from cfnlint.template.transforms._language_extensions import _Transform

_TEMPLATE = {
    "Transform": "AWS::LanguageExtensions",
    "Parameters": {},
    "Resources": {
        "Fn::ForEach::L": [
            "L",
            [
                {"Ref": "UnresolvableParam"},
                {"Ref": "AnotherUnresolvableParam"},
            ],
            {
                "Bucket${L}": {
                    "Type": "AWS::S3::Bucket",
                }
            },
        ]
    },
}

TARGET_CODE = _Transform._walk.__code__

sequences = []
for _ in range(15):
    seq = []
    def tracer(frame, event, arg):
        if event == 'line' and frame.f_code is TARGET_CODE:
            seq.append(frame.f_lineno)
        return tracer

    sys.settrace(tracer)
    try:
        cfn = Template("foo.yaml", _TEMPLATE, ["us-east-1"])
        _Transform().transform(cfn)
    finally:
        sys.settrace(None)
    sequences.append(tuple(seq))

print('runs', len(sequences))
print('all_equal', len(set(sequences)) == 1)
print('lengths', sorted({len(s) for s in sequences}))
print('first20', sequences[0][:20])
